CREATE TABLE IF NOT EXISTS coin_wallets(user_id INTEGER PRIMARY KEY,balance INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS coin_history(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,amount INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assessments(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,type TEXT NOT NULL,subject TEXT NOT NULL,class_name TEXT NOT NULL,reward INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assessment_questions(id INTEGER PRIMARY KEY AUTOINCREMENT,assessment_id INTEGER NOT NULL,question TEXT NOT NULL,options_json TEXT NOT NULL,correct_index INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS assessment_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,assessment_id INTEGER NOT NULL,student_id INTEGER NOT NULL,score INTEGER NOT NULL,total INTEGER NOT NULL,reward INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(assessment_id,student_id));
CREATE TABLE IF NOT EXISTS shop_items(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT NOT NULL,price INTEGER NOT NULL,stock INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS shop_orders(id INTEGER PRIMARY KEY AUTOINCREMENT,item_id INTEGER NOT NULL,student_id INTEGER NOT NULL,price INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL);
